(r, big) => {
  const nd = v => ({ v, L: null, R: null });
  const ser = t => { const o = [], q = [t]; for (let i = 0; i < q.length; i++) { const x = q[i]; if (x) { o.push(x.v); q.push(x.L, x.R); } else o.push(null); } while (o.length && o[o.length - 1] === null) o.pop(); return o; };
  const bst = vals => { let t = null; for (const v of vals) { const x = nd(v); if (!t) { t = x; continue; } let c = t; for (;;) { const k = v < c.v ? "L" : "R"; if (!c[k]) { c[k] = x; break; } c = c[k]; } } return t; };
  let vals = big ? r.distinct(20000, -1000000000, 1000000000) : r.distinct(r.int(2, 10), -20, 20);
  if (!big && r.bool(0.2)) vals.sort((a, b) => r.bool() ? a - b : b - a); // sometimes a lopsided tree
  const [p, q] = r.shuffle(vals).slice(0, 2);
  return [ser(bst(vals)), p, q];
}

