function sharedAncestor(root: TreeNode | null, p: number, q: number): number {
  const path = (target: number): number[] => {
    const out: number[] = [];
    let node = root;
    while (node) {
      out.push(node.val);
      if (node.val === target) break;
      node = target < node.val ? node.left : node.right;
    }
    return out;
  };
  const a = path(p), b = path(q);
  let i = 0;
  while (i + 1 < a.length && i + 1 < b.length && a[i + 1] === b[i + 1]) i++;
  return a[i];
}

