        def path(target):
            out, node = [], root
            while node:
                out.append(node.val)
                if node.val == target:
                    break
                node = node.left if target < node.val else node.right
            return out

        a, b = path(p), path(q)
        i = 0
        while i + 1 < len(a) and i + 1 < len(b) and a[i + 1] == b[i + 1]:
            i += 1
        return a[i]

